function equalStringSets(
  left: readonly string[],
  right: readonly string[],
): boolean {
  if (left.length !== right.length) return false;
  const rightSet = new Set(right);
  return (
    rightSet.size === right.length && left.every((value) => rightSet.has(value))
  );
}

function resourcePolicyMatchesSnapshot(
  snapshot: PolicySnapshot,
  resourcePolicy: DefinedResourcePolicy,
): boolean {
  const purposeIds = snapshot.policy.purposes.map((purpose) => purpose.id);
  if (!equalStringSets(purposeIds, resourcePolicy.purposeIds)) return false;

  const knownPurposeIds = new Set(purposeIds);
  const serviceIds = new Set(
    resourcePolicy.services.map((service) => service.id),
  );
  if (
    serviceIds.size !== resourcePolicy.services.length ||
    resourcePolicy.services.some((service) => service.id.trim().length === 0)
  ) {
    return false;
  }

  const resourceIds = new Set<string>();
  for (const resource of resourcePolicy.resources) {
    if (
      resource.id.trim().length === 0 ||
      resourceIds.has(resource.id) ||
      !serviceIds.has(resource.serviceId) ||
      (resource.access === "optional" && resource.purposeIds.length === 0) ||
      (resource.access === "declared-exception" &&
        resource.exceptionReason.trim().length === 0) ||
      resource.purposeIds.some((purposeId) => !knownPurposeIds.has(purposeId))
    ) {
      return false;
    }
    resourceIds.add(resource.id);
  }
  return true;
}

